// ── Step 1: Load the current issue and derive a keyword fingerprint ──────────
const selfKey = api.context.issueKey;
// Defensive: on a create-style transition the key can be absent — no-op safely.
if (!selfKey) {
  api.log("dup-linker: no issue key in context; skipping");
  return;
}
const projectKey = api.context.projectKey || selfKey.split("-")[0];
const issue = await api.getIssue(selfKey);
const summary = (issue.fields.summary || "").toString();

const STOP = new Set(["the","a","an","and","or","for","to","of","in","on","with","as","is","are","be","by","at","from","this","that","it","we","you","not","but","if","then","when","fix","bug","issue","error","fails","failing","broken","unable","cannot","need","needs"]);
const tokenize = (s) => Array.from(new Set(
  (String(s).toLowerCase().match(/[a-z0-9]{4,}/g) || []).filter((w) => !STOP.has(w))
));
const selfTokens = tokenize(summary);

// No usable keywords → nothing to match on. Mark reviewed and stop (idempotent).
if (selfTokens.length < 2) {
  await api.addLabels("dup-checked");
  await api.removeLabels("has-duplicate", "possible-duplicate");
  api.log(`dup-linker: only ${selfTokens.length} keyword(s) in summary; marked dup-checked`);
  return;
}

// ── Step 2: Read the stateful link ledger (idempotency backbone) ─────────────
const LEDGER_KEY = "cognirunner.dupLinks";
let ledger = await api.getProperty(LEDGER_KEY);
if (!ledger || typeof ledger !== "object" || !Array.isArray(ledger.linked)) {
  ledger = { linked: [], updatedAt: null, runs: 0 };
}
const alreadyLinked = new Set(ledger.linked);

// ── Step 3: Build a scoped, self- and ledger-excluding JQL, then search ──────
const topKeywords = selfTokens.slice(0, 6);
const orClause = topKeywords.map((w) => `summary ~ "${w}"`).join(" OR ");
const excludeKeys = [selfKey, ...ledger.linked].slice(0, 40);
const baseJql = `project = "${projectKey}" AND (${orClause}) AND key NOT IN (${excludeKeys.join(",")}) ORDER BY created ASC`;

let raw;
try {
  raw = await api.searchJql(baseJql);
} catch (e) {
  // A malformed/over-long JQL can 400 — retry with just the strongest keyword.
  api.log(`dup-linker: primary JQL failed (${e.message}); retrying single-keyword`);
  try {
    raw = await api.searchJql(`project = "${projectKey}" AND summary ~ "${topKeywords[0]}" AND key != ${selfKey}`);
  } catch (e2) {
    await api.addLabels("dup-search-failed");
    api.log(`dup-linker: fallback JQL also failed (${e2.message}); aborting safely`);
    return;
  }
}
// Handle BOTH the { issues:[...] } object and a bare-array response shape.
const candidates = Array.isArray(raw) ? raw : (raw && raw.issues) || [];

// ── Step 4: Score candidates by keyword-set overlap (Jaccard) ────────────────
const selfSet = new Set(selfTokens);
const scored = candidates.map((c) => {
  const ct = tokenize((c.fields && c.fields.summary) || "");
  const inter = ct.filter((w) => selfSet.has(w));
  const union = new Set([...selfTokens, ...ct]).size || 1;
  return { key: c.key, overlap: inter.length, jaccard: inter.length / union, shared: inter };
});
// Strong = shares >=2 keywords AND Jaccard >= 0.34 and not already linked.
const strong = scored
  .filter((s) => s.overlap >= 2 && s.jaccard >= 0.34 && !alreadyLinked.has(s.key))
  .sort((a, b) => b.jaccard - a.jaccard || b.overlap - a.overlap)
  .slice(0, 3);
const weak = scored.filter((s) => s.overlap >= 1 && !strong.some((x) => x.key === s.key));

api.log(`dup-linker: ${candidates.length} candidate(s); ${strong.length} strong, ${weak.length} weak; ledger=${ledger.linked.length}`);

// ── Step 5: Branch on the classification ─────────────────────────────────────
if (strong.length > 0) {
  const newlyLinked = [];
  for (const m of strong) {
    try {
      await api.createIssueLink(m.key, "Relates");   // links THIS issue → match
      newlyLinked.push(m.key);
    } catch (e) {
      api.log(`dup-linker: link to ${m.key} failed (${e.message}) — continuing`);
    }
  }
  if (newlyLinked.length > 0) {
    // One consolidated ADF comment naming the freshly linked keys + shared terms.
    const listItems = strong
      .filter((m) => newlyLinked.includes(m.key))
      .map((m) => ({
        type: "listItem",
        content: [{ type: "paragraph", content: [
          { type: "text", text: `${m.key} `, marks: [{ type: "strong" }] },
          { type: "text", text: `— ${m.overlap} shared: ${m.shared.slice(0, 5).join(", ")}` },
        ] }],
      }));
    const adf = { type: "doc", version: 1, content: [
      { type: "paragraph", content: [{ type: "text", text: "CogniRunner found likely related issue(s) by keyword overlap and linked them:" }] },
      { type: "bulletList", content: listItems },
    ] };
    try { await api.addComment(adf); } catch (e) { api.log(`dup-linker: comment failed (${e.message})`); }

    // Persist the updated ledger (read-modify-write) so re-fires never re-link/re-comment.
    ledger.linked = Array.from(new Set([...ledger.linked, ...newlyLinked])).slice(0, 100);
    ledger.updatedAt = new Date().toISOString();
    ledger.runs = (ledger.runs || 0) + 1;
    await api.setProperty(LEDGER_KEY, ledger);

    await api.addLabels("has-duplicate");
    await api.removeLabels("unique", "possible-duplicate");
  }
} else if (weak.length > 0) {
  await api.addLabels("possible-duplicate");
  await api.removeLabels("unique");
  api.log(`dup-linker: only weak overlap (top ${weak[0].key} shares ${weak[0].overlap}); flagged possible-duplicate`);
} else {
  // No CURRENT matches. Linked duplicates are excluded from the JQL/scoring, so
  // a re-fire lands here even though the ledger records real duplicates — keep the
  // has-duplicate state stable and only declare "unique" when the ledger is empty.
  if (ledger.linked.length > 0) {
    await api.addLabels("has-duplicate");
    await api.removeLabels("unique", "possible-duplicate");
    api.log(`dup-linker: no new matches but ${ledger.linked.length} previously linked; kept has-duplicate`);
  } else {
    await api.addLabels("unique");
    await api.removeLabels("possible-duplicate", "has-duplicate");
  }
}

// ── Step 6: Always leave a bounded "checked" breadcrumb (re-runnable) ─────────
await api.setProperty("cognirunner.dupChecked", { at: new Date().toISOString(), candidates: candidates.length, strong: strong.length });

// ── Step 1: Fingerprint the current issue ────────────────────────────────────
const selfKey = api.context.issueKey;
const projectKey = api.context.projectKey || selfKey.split("-")[0];
const selfNum = parseInt(String(selfKey).split("-")[1], 10) || 0;
const issue = await api.getIssue(selfKey);
const summary = (issue.fields.summary || "").toString();

const STOP = new Set(["the","a","an","and","or","for","to","of","in","on","with","as","is","are","be","by","at","from","this","that","it","we","you","not","but","if","then","when","fix","bug","issue","error","fails","failing","broken","unable","cannot","need","needs"]);
const tokenize = (s) => Array.from(new Set(
  (String(s).toLowerCase().match(/[a-z0-9]{4,}/g) || []).filter((w) => !STOP.has(w))
));
const selfTokens = tokenize(summary);
if (selfTokens.length < 2) {
  await api.addLabels("triage-skipped");
  api.log("dup-triage: too few keywords; skipped");
  return;
}

// ── Step 2: Load the stateful triage record (role + dedup ledger) ────────────
const STATE_KEY = "cognirunner.triageState";
let state = await api.getProperty(STATE_KEY);
if (!state || typeof state !== "object") {
  state = { role: null, canonical: null, relatedCount: 0, linked: [], runs: 0 };
}
if (!Array.isArray(state.linked)) state.linked = [];
const linkedSet = new Set(state.linked);

// ── Step 3: Search overlapping issues; score peers by shared keywords ────────
const kw = selfTokens.slice(0, 6);
const orClause = kw.map((w) => `summary ~ "${w}"`).join(" OR ");
let raw;
try {
  raw = await api.searchJql(`project = "${projectKey}" AND (${orClause}) AND key != ${selfKey} ORDER BY created ASC`);
} catch (e) {
  api.log(`dup-triage: JQL failed (${e.message}); marking triage-error`);
  await api.addLabels("triage-error");
  return;
}
// Handle BOTH the { issues:[...] } object and a bare-array response shape.
const hits = Array.isArray(raw) ? raw : (raw && raw.issues) || [];
const selfSet = new Set(selfTokens);
const peers = hits.map((h) => {
  const ht = tokenize((h.fields && h.fields.summary) || "");
  const shared = ht.filter((w) => selfSet.has(w));
  return {
    key: h.key,
    num: parseInt(String(h.key).split("-")[1], 10) || 0,
    shared: shared.length,
    terms: shared,
    assignee: h.fields && h.fields.assignee ? h.fields.assignee.accountId : null,
  };
}).filter((p) => p.shared >= 2).sort((a, b) => a.num - b.num);

// ── Step 4: Empty branch — no cluster, reset role to "unique" ────────────────
if (peers.length === 0) {
  state.role = "unique"; state.canonical = null; state.relatedCount = 0;
  state.runs = (state.runs || 0) + 1;
  await api.setProperty(STATE_KEY, state);
  await api.addLabels("dup-unique");
  await api.removeLabels("dup-duplicate", "dup-canonical");
  api.log("dup-triage: no overlapping peers; role=unique");
  return;
}

// ── Step 5: Decide role by seniority (oldest key number = canonical) ─────────
const oldestPeer = peers[0];
const iAmCanonical = selfNum <= oldestPeer.num;   // no older overlapping peer exists

if (!iAmCanonical) {
  // DUPLICATE branch: link to the older canonical, comment, route owner, audit.
  const canon = oldestPeer;
  state.role = "duplicate"; state.canonical = canon.key;

  if (!linkedSet.has(canon.key)) {
    try {
      await api.createIssueLink(canon.key, "Duplicate");   // "this duplicates canon"
      state.linked.push(canon.key);

      const others = peers.filter((p) => p.key !== canon.key).slice(0, 5).map((p) => p.key);
      const adf = { type: "doc", version: 1, content: [
        { type: "paragraph", content: [
          { type: "text", text: "Likely duplicate of " },
          { type: "text", text: canon.key, marks: [{ type: "strong" }] },
          { type: "text", text: ` (${canon.shared} shared: ${canon.terms.slice(0, 5).join(", ")}).` },
        ] },
        ...(others.length ? [{ type: "paragraph", content: [{ type: "text", text: `Other cluster members: ${others.join(", ")}.` }] }] : []),
      ] };
      await api.addComment(adf);

      // Route to the canonical owner so the cluster lands with one person.
      const curAssignee = issue.fields.assignee ? issue.fields.assignee.accountId : null;
      if (canon.assignee && canon.assignee !== curAssignee) {
        try { await api.setAssignee(canon.assignee); } catch (e) { api.log(`dup-triage: reassign failed (${e.message})`); }
      }
      // Bounded audit worklog — only on the FIRST-time link, so it can't accumulate.
      try { await api.addWorklog(60, `CogniRunner: classified as duplicate of ${canon.key}`); } catch (e) { api.log(`dup-triage: worklog skipped (${e.message})`); }
    } catch (e) {
      api.log(`dup-triage: link to canonical ${canon.key} failed (${e.message})`);
    }
  }
  await api.addLabels("dup-duplicate");
  await api.removeLabels("dup-unique", "dup-canonical");
} else {
  // CANONICAL branch: this senior issue becomes the cluster hub.
  state.role = "canonical"; state.canonical = selfKey;
  const newer = peers.filter((p) => p.num > selfNum);
  const freshNewer = newer.filter((p) => !linkedSet.has(p.key)).slice(0, 3);
  const linkedNow = [];
  for (const p of freshNewer) {
    try { await api.createIssueLink(p.key, "Relates"); state.linked.push(p.key); linkedNow.push(p.key); }
    catch (e) { api.log(`dup-triage: hub link to ${p.key} failed (${e.message})`); }
  }
  if (linkedNow.length > 0) {
    const adf = { type: "doc", version: 1, content: [
      { type: "paragraph", content: [
        { type: "text", text: "This is the canonical issue for a duplicate cluster. Newly linked related issue(s): " },
        { type: "text", text: linkedNow.join(", "), marks: [{ type: "strong" }] },
        { type: "text", text: "." },
      ] },
    ] };
    try { await api.addComment(adf); } catch (e) { api.log(`dup-triage: hub comment failed (${e.message})`); }
  }
  state.relatedCount = Array.from(new Set(state.linked)).length;
  await api.addLabels("dup-canonical");
  await api.removeLabels("dup-unique", "dup-duplicate");
}

// ── Step 6: Persist the evolved state (dedup ledger, bump run counter) ────────
state.linked = Array.from(new Set(state.linked)).slice(0, 100);
state.runs = (state.runs || 0) + 1;
await api.setProperty(STATE_KEY, state);
api.log(`dup-triage: role=${state.role} canonical=${state.canonical} linked=${state.linked.length} runs=${state.runs}`);

// STATEFUL AUDIT-TRAIL + ESCALATION
// Read-modify-write an on-issue audit ledger; escalate (worklog + ADF comment + label)
// a BOUNDED number of times once the recorded event count crosses threshold bands.
const PROP_KEY = "cogni-audit-ledger";
const MAX_ENTRIES = 50;        // cap the stored array so the property never grows unbounded
const THRESHOLD = 10;          // events per escalation band
const MAX_ESCALATIONS = 3;     // hard cap on comments/worklogs/labels — safe to fire forever
const REVIEW_SECONDS = 900;    // 15m of "audit review" logged per escalation

const key = api.context.issueKey;

// ---- 1. Load current issue (best-effort; the audit still works if this fails) ----
let issue = null;
try {
  issue = await api.getIssue(key);
} catch (e) {
  api.log("audit: getIssue failed, continuing with minimal entry:", e.message);
}
const status = issue && issue.fields && issue.fields.status ? issue.fields.status.name : "(unknown)";
const actor = issue && issue.fields && issue.fields.assignee ? issue.fields.assignee.displayName : "(unassigned)";

// ---- 2. Read + repair the ledger property (defensive against corrupt/legacy shapes) ----
let ledger = null;
try {
  ledger = await api.getProperty(PROP_KEY);
} catch (e) {
  api.log("audit: getProperty failed:", e.message);
}
if (!ledger || typeof ledger !== "object" || !Array.isArray(ledger.entries)) {
  ledger = { entries: [], totalCount: 0, escalationsSent: 0, lastFingerprint: null };
}
if (typeof ledger.totalCount !== "number") ledger.totalCount = ledger.entries.length;
if (typeof ledger.escalationsSent !== "number") ledger.escalationsSent = 0;

const nowIso = new Date().toISOString();
const fingerprint = status + "|" + actor;

// ---- 3. Rapid-duplicate idempotency guard, then append + bound the array ----
let appended = false;
const last = ledger.entries[ledger.entries.length - 1];
const isRapidDup = last && last.fp === fingerprint && (Date.parse(nowIso) - Date.parse(last.ts)) < 3000;
if (isRapidDup) {
  api.log("audit: rapid duplicate fire ignored (fp=" + fingerprint + ")");
} else {
  ledger.entries.push({ ts: nowIso, status: status, actor: actor, fp: fingerprint });
  ledger.totalCount += 1;
  appended = true;
  if (ledger.entries.length > MAX_ENTRIES) {
    ledger.entries = ledger.entries.slice(ledger.entries.length - MAX_ENTRIES);
  }
}
ledger.lastFingerprint = fingerprint;

// ---- 4. Decide whether we cross a NEW escalation band (escalate-once-per-band, capped) ----
const bandsEarned = Math.floor(ledger.totalCount / THRESHOLD);
const shouldEscalate =
  appended &&
  bandsEarned > ledger.escalationsSent &&
  ledger.escalationsSent < MAX_ESCALATIONS;

// ---- 5. Persist the ledger BEFORE side effects so a later failure can't lose the count ----
try {
  await api.setProperty(PROP_KEY, ledger);
} catch (e) {
  api.log("audit: setProperty failed — count may be lost this fire:", e.message);
}

// ---- 6. Escalation branch (bounded number of times) ----
if (shouldEscalate) {
  const band = ledger.escalationsSent + 1;
  api.log("audit: ESCALATING band " + band + " at totalCount=" + ledger.totalCount);

  // 6a. worklog the audit-review overhead
  try {
    await api.addWorklog(REVIEW_SECONDS, "Automated audit-trail review (escalation band " + band + ", " + ledger.totalCount + " recorded events).");
  } catch (e) { api.log("audit: addWorklog failed:", e.message); }

  // 6b. escalation ADF comment naming the count + the last few timestamped events
  const recent = ledger.entries.slice(-5).map(function (ev) {
    return { type: "listItem", content: [ { type: "paragraph", content: [ { type: "text", text: ev.ts + " — " + ev.status + " (" + ev.actor + ")" } ] } ] };
  });
  const commentBody = {
    type: "doc", version: 1, content: [
      { type: "heading", attrs: { level: 3 }, content: [ { type: "text", text: "Audit escalation (band " + band + " of " + MAX_ESCALATIONS + ")" } ] },
      { type: "paragraph", content: [
        { type: "text", text: "This issue has crossed " + ledger.totalCount + " recorded audit events (threshold " + THRESHOLD + "). " },
        { type: "text", text: "Escalating for review.", marks: [ { type: "strong" } ] }
      ] },
      { type: "paragraph", content: [ { type: "text", text: "Most recent events:" } ] },
      { type: "bulletList", content: recent.length ? recent : [ { type: "listItem", content: [ { type: "paragraph", content: [ { type: "text", text: "(none)" } ] } ] } ] }
    ]
  };
  try {
    await api.addComment(commentBody);
  } catch (e) { api.log("audit: addComment failed:", e.message); }

  // 6c. label it (merge-add, safe under concurrent post-functions)
  try {
    await api.addLabels("escalated", "audit-band-" + band);
  } catch (e) { api.log("audit: addLabels failed:", e.message); }

  // 6d. record that this band was escalated so we never re-escalate it
  ledger.escalationsSent = band;
  try {
    await api.setProperty(PROP_KEY, ledger);
  } catch (e) { api.log("audit: setProperty (post-escalation) failed:", e.message); }
} else if (ledger.escalationsSent >= MAX_ESCALATIONS) {
  api.log("audit: escalation cap reached (" + MAX_ESCALATIONS + ") — recording events only.");
}

// ---- 7. Hand a summary to the next step in the chain ----
return {
  recorded: appended,
  totalCount: ledger.totalCount,
  storedEntries: ledger.entries.length,
  escalationsSent: ledger.escalationsSent,
  escalatedThisFire: shouldEscalate
};

// STATEFUL REWORK/BOUNCE LEDGER + CROSS-ISSUE ESCALATION ROLL-UP
// Records each transition into a bounce ledger on the issue (read-modify-write).
// Once bounces cross a threshold it LINKS to an existing escalation-tracker issue
// (found via JQL — never created, so it can't flood), logs review overhead, and posts
// an ADF roll-up comment. Escalations are hard-capped so it is safe to fire repeatedly.
const PROP_KEY = "cogni-bounce-ledger";
const MAX_ENTRIES = 25;
const THRESHOLD = 5;
const MAX_ESCALATIONS = 2;
const REVIEW_SECONDS = 1800;
const TRACKER_LABEL = "escalation-tracker";

const key = api.context.issueKey;
const projectKey = api.context.projectKey || key.split("-")[0];

// ---- 1. Load the issue + derive a 'reason' from a custom select (best-effort) ----
let issue = null;
try { issue = await api.getIssue(key); }
catch (e) { api.log("bounce: getIssue failed:", e.message); }

function selVal(f) { return f && typeof f === "object" ? (f.value || f.name || null) : (f || null); }
const reason = issue && issue.fields ? (selVal(issue.fields.customfield_10281) || (issue.fields.priority && issue.fields.priority.name) || "n/a") : "n/a";
const status = issue && issue.fields && issue.fields.status ? issue.fields.status.name : "(unknown)";

// ---- 2. Read + normalize the bounce ledger property ----
let led = null;
try { led = await api.getProperty(PROP_KEY); }
catch (e) { api.log("bounce: getProperty failed:", e.message); }
if (!led || typeof led !== "object" || !Array.isArray(led.bounces)) {
  led = { bounces: [], total: 0, escalationsSent: 0 };
}
if (typeof led.total !== "number") led.total = led.bounces.length;
if (typeof led.escalationsSent !== "number") led.escalationsSent = 0;

// ---- 3. Rapid-duplicate guard, then append + bound the array ----
const nowIso = new Date().toISOString();
const prev = led.bounces[led.bounces.length - 1];
const dup = prev && prev.status === status && (Date.parse(nowIso) - Date.parse(prev.ts)) < 3000;
let recorded = false;
if (dup) {
  api.log("bounce: rapid duplicate ignored");
} else {
  led.bounces.push({ ts: nowIso, status: status, reason: reason });
  led.total += 1;
  recorded = true;
  if (led.bounces.length > MAX_ENTRIES) led.bounces = led.bounces.slice(-MAX_ENTRIES);
}

// ---- 4. Band decision (escalate-once-per-band, capped) + ATOMIC persist ----
// Bump escalationsSent BEFORE the single persist so the counter and the appended
// bounce are committed together. Otherwise a later persist-failure could leave the
// ledger grown but the counter stuck, re-escalating the same band on every fire.
const bands = Math.floor(led.total / THRESHOLD);
const escalate = recorded && bands > led.escalationsSent && led.escalationsSent < MAX_ESCALATIONS;
const band = led.escalationsSent + 1;
if (escalate) led.escalationsSent = band;
try { await api.setProperty(PROP_KEY, led); }
catch (e) { api.log("bounce: setProperty failed:", e.message); }

// ---- 5. Escalation branch: cross-issue link + worklog + ADF comment + labels ----
let linkedTo = null;
if (escalate) {
  // 5a. find an existing escalation-tracker in the project (JQL). NEVER create one.
  try {
    const r = await api.searchJql('project = ' + projectKey + ' AND labels = "' + TRACKER_LABEL + '" AND key != ' + key + ' ORDER BY created ASC');
    const arr = Array.isArray(r) ? r : (r && r.issues) || [];
    if (arr.length) {
      linkedTo = arr[0].key;
      // dedup: only link if this issue isn't already linked to the tracker
      let already = false;
      if (issue && issue.fields && Array.isArray(issue.fields.issuelinks)) {
        already = issue.fields.issuelinks.some(function (l) {
          const ok = l.outwardIssue && l.outwardIssue.key === linkedTo;
          const ik = l.inwardIssue && l.inwardIssue.key === linkedTo;
          return ok || ik;
        });
      }
      if (!already) {
        try { await api.createIssueLink(linkedTo, "Relates"); }
        catch (e) { api.log("bounce: createIssueLink failed:", e.message); linkedTo = null; }
      } else {
        api.log("bounce: already linked to tracker " + linkedTo);
      }
    } else {
      api.log("bounce: no escalation-tracker found in " + projectKey + " (not creating one)");
    }
  } catch (e) { api.log("bounce: JQL search failed:", e.message); }

  // 5b. worklog the rework-review overhead
  try {
    await api.addWorklog(REVIEW_SECONDS, "Rework roll-up review (band " + band + ", " + led.total + " bounces).");
  } catch (e) { api.log("bounce: addWorklog failed:", e.message); }

  // 5c. ADF roll-up comment with the last few bounces + their reasons
  const items = led.bounces.slice(-5).map(function (b) {
    return { type: "listItem", content: [ { type: "paragraph", content: [ { type: "text", text: b.ts + " -> " + b.status + " (reason: " + b.reason + ")" } ] } ] };
  });
  const body = {
    type: "doc", version: 1, content: [
      { type: "heading", attrs: { level: 3 }, content: [ { type: "text", text: "Rework escalation — " + led.total + " bounces (band " + band + "/" + MAX_ESCALATIONS + ")" } ] },
      { type: "paragraph", content: [
        { type: "text", text: "Threshold of " + THRESHOLD + " exceeded. " },
        { type: "text", text: linkedTo ? ("Linked to tracker " + linkedTo + ".") : "No tracker issue found to link.", marks: [ { type: "strong" } ] }
      ] },
      { type: "bulletList", content: items.length ? items : [ { type: "listItem", content: [ { type: "paragraph", content: [ { type: "text", text: "(none)" } ] } ] } ] }
    ]
  };
