      { type: "text", text: `${done}/${total} done` },
      ...(newlyCompleted > 0 ? [{ type: "text", text: ` (+${newlyCompleted} since last update)`, marks: [{ type: "strong" }] }] : []),
      ...(truncated ? [{ type: "text", text: " — showing first 20" }] : []),
    ] },
    { type: "table", attrs: { isNumberColumnEnabled: false, layout: "default" }, content: [header, ...rows] },
    ...(laggard ? [{ type: "paragraph", content: [{ type: "text", text: `Longest-waiting open sibling: ${laggard.key} (${laggard.status})` }] }] : []),
  ] };
  try {
    await api.addComment(doc);
  } catch (e) {
    api.log("ADF table comment failed, falling back to bullets:", e && e.message);
    const bullets = Object.keys(hist).sort().map((k) => ({
      type: "listItem", content: [{ type: "paragraph", content: [{ type: "text", text: `${k}: ${hist[k]}` }] }],
    }));
    try {
      await api.addComment({ type: "doc", version: 1, content: [
        { type: "paragraph", content: [{ type: "text", text: `Sibling rollup — ${done}/${total} done (${pct}%)` }] },
        { type: "bulletList", content: bullets },
      ] });
    } catch (e2) { api.log("fallback comment failed too:", e2 && e2.message); }
  }
} else {
  api.log("Rollup unchanged since last fire — skipping comment.");
}

return rollup;

// === Sibling SLA / risk rollup with breach-streak state (safe to re-fire) ===
const SELF = api.context.issueKey;
const PROJ = api.context.projectKey || SELF.split("-")[0];
const esc = (s) => String(s == null ? "" : s).replace(/"/g, '\\"');
const TODAY = new Date().toISOString().slice(0, 10); // YYYY-MM-DD

// 1) Load issue, choose the sibling cohort (parent -> component -> label)
const cur = await api.getIssue(SELF);
const f = cur.fields || {};
let jql = null, cohortKind = null;
if (f.parent && f.parent.key) {
  jql = `parent = ${f.parent.key} ORDER BY duedate ASC`;
  cohortKind = "parent:" + f.parent.key;
} else if (Array.isArray(f.components) && f.components[0] && f.components[0].name) {
  jql = `project = ${PROJ} AND component = "${esc(f.components[0].name)}" ORDER BY duedate ASC`;
  cohortKind = "component:" + f.components[0].name;
} else if (Array.isArray(f.labels) && f.labels.length) {
  jql = `project = ${PROJ} AND labels = "${esc(f.labels[0])}" ORDER BY duedate ASC`;
  cohortKind = "label:" + f.labels[0];
}
if (!jql) {
  api.log("SLA rollup: no cohort key to group by.");
  return { ok: false, reason: "no-cohort" };
}

// 2) Fetch cohort (both shapes); guard against no siblings
const raw = await api.searchJql(jql);
const cohort = Array.isArray(raw) ? raw : (raw && raw.issues) || [];
const others = cohort.filter((i) => i && i.key && i.key !== SELF);
if (others.length === 0) {
  api.log(`SLA rollup: ${cohortKind} solo — nothing to aggregate.`);
  await api.setProperty("cogni-sibling-sla", { ok: false, reason: "solo", at: new Date().toISOString() });
  return { ok: false, reason: "solo", cohort: cohortKind };
}

// 3) Aggregate a priority histogram + the overdue set (open AND past due date)
const OPEN = (it) => {
  const st = it.fields && it.fields.status;
  const cat = st && st.statusCategory && st.statusCategory.key;
  if (cat) return cat !== "done";
  return !(it.fields && it.fields.resolution);
};
const prio = {};
const overdue = [];
let earliestDue = null;
for (const it of cohort) {
  const p = (it.fields && it.fields.priority && it.fields.priority.name) || "None";
  prio[p] = (prio[p] || 0) + 1;
  const due = it.fields && it.fields.duedate;
  if (due && OPEN(it)) {
    if (!earliestDue || due < earliestDue) earliestDue = due;
    if (due < TODAY) overdue.push({ key: it.key, due, priority: p });
  }
}
const total = cohort.length;
const overdueCount = overdue.length;
const risk = overdueCount === 0 ? "On track" : overdueCount >= 3 ? "Critical" : "At risk";
api.log(`SLA ${cohortKind}: ${overdueCount} overdue of ${total}; risk=${risk}`, prio);

// 4) Stateful breach-streak counter (increments on breach, resets when clear)
let state = null;
try { state = await api.getProperty("cogni-sibling-sla"); } catch (e) { api.log("state read failed:", e && e.message); }
const prevStreak = state && typeof state.streak === "number" ? state.streak : 0;
const prevLinked = state && Array.isArray(state.linked) ? state.linked : [];
const streak = overdueCount > 0 ? prevStreak + 1 : 0;

// 5) Cross-link each NEW overdue sibling once (idempotent via stored linked set)
const linkedSet = new Set(prevLinked);
const newlyLinked = [];
for (const o of overdue) {
  if (linkedSet.has(o.key) || o.key === SELF) continue;
  try {
    await api.createIssueLink(o.key, "Relates");
    linkedSet.add(o.key);
    newlyLinked.push(o.key);
  } catch (e) { api.log("link failed for " + o.key + ":", e && e.message); }
}
const stillOverdue = new Set(overdue.map((o) => o.key));
const linkedKept = [...linkedSet].filter((k) => stillOverdue.has(k)); // bound the set

// 6) Persist: risk-banner text, overdue-count number, earliest-due date, property
const banner = `${risk}: ${overdueCount} overdue / ${total} in ${cohortKind}${streak > 1 ? ` (streak ${streak})` : ""}`;
const fields = { customfield_10280: banner, customfield_10282: overdueCount };
if (earliestDue) fields.customfield_10283 = earliestDue; // date field, already YYYY-MM-DD
try { await api.updateIssue(SELF, fields); } catch (e) { api.log("field write failed:", e && e.message); }
const rollup = {
  ok: true, cohort: cohortKind, total, overdueCount, risk, streak, earliestDue,
  priorities: prio, linked: linkedKept, overdue: overdue.map((o) => o.key),
  at: new Date().toISOString(),
};
await api.setProperty("cogni-sibling-sla", rollup);

// 7) Branch: escalate ONCE after 3 consecutive breach fires (label-guarded)
const labels = f.labels || [];
if (streak >= 3 && !labels.includes("sla-escalated")) {
  try {
    await api.addLabels("sla-escalated");
    await api.addWorklog(300, "Auto-escalation: sibling SLA breach streak reached " + streak);
    api.log("Escalated after streak " + streak);
  } catch (e) { api.log("escalation failed:", e && e.message); }
} else if (overdueCount === 0 && labels.includes("sla-escalated")) {
  try { await api.removeLabels("sla-escalated"); api.log("Cleared escalation — cohort back on track."); } catch (e) { api.log("clear failed:", e && e.message); }
}

// 8) ADF priority-table comment — only when the overdue set changed vs last fire
const prevOverdueKey = state && Array.isArray(state.overdue) ? state.overdue.slice().sort().join(",") : "";
const nowOverdueKey = overdue.map((o) => o.key).sort().join(",");
if (prevOverdueKey !== nowOverdueKey) {
  const header = { type: "tableRow", content: [
    { type: "tableHeader", content: [{ type: "paragraph", content: [{ type: "text", text: "Priority", marks: [{ type: "strong" }] }] }] },
    { type: "tableHeader", content: [{ type: "paragraph", content: [{ type: "text", text: "Count", marks: [{ type: "strong" }] }] }] },
  ] };
  const rows = Object.keys(prio).sort().map((k) => ({ type: "tableRow", content: [
    { type: "tableCell", content: [{ type: "paragraph", content: [{ type: "text", text: k }] }] },
    { type: "tableCell", content: [{ type: "paragraph", content: [{ type: "text", text: String(prio[k]) }] }] },
  ] }));
  const overdueLines = overdue.length
    ? overdue.slice(0, 10).map((o) => ({ type: "listItem", content: [{ type: "paragraph", content: [{ type: "text", text: `${o.key} — due ${o.due} (${o.priority})` }] }] }))
    : [{ type: "listItem", content: [{ type: "paragraph", content: [{ type: "text", text: "none" }] }] }];
  const doc = { type: "doc", version: 1, content: [
    { type: "heading", attrs: { level: 3 }, content: [{ type: "text", text: `Sibling SLA rollup — ${risk}` }] },
    { type: "table", attrs: { isNumberColumnEnabled: false, layout: "default" }, content: [header, ...rows] },
    { type: "paragraph", content: [{ type: "text", text: `Overdue (${overdueCount})`, marks: [{ type: "strong" }] }] },
    { type: "bulletList", content: overdueLines },
    ...(newlyLinked.length ? [{ type: "paragraph", content: [{ type: "text", text: `Newly linked: ${newlyLinked.join(", ")}` }] }] : []),
  ] };
  try {
    await api.addComment(doc);
  } catch (e) {
    api.log("table comment failed, plain fallback:", e && e.message);
    try { await api.addComment(`Sibling SLA rollup — ${risk}: ${overdueCount} overdue of ${total}. Overdue: ${overdue.map((o) => o.key).join(", ") || "none"}`); }
    catch (e2) { api.log("fallback failed:", e2 && e2.message); }
  }
} else {
  api.log("Overdue set unchanged — no comment.");
}

return rollup;

const MARKER = "cogni-runbook-enriched";
const key = api.context.issueKey;
const projectKey = (api.context && api.context.projectKey) || key.split("-")[0];

// Step 1 — idempotency gate: an existing marker property means this is a re-fire -> no-op.
let marker = null;
try {
  marker = await api.getProperty(MARKER);
} catch (e) {
  api.log("Could not read marker property, treating as absent:", e.message);
}
if (marker && marker.provisioned) {
  api.log("Runbook already provisioned on " + marker.at + " (worklog " + (marker.worklogId || "n/a") + "). Re-fire is a no-op.");
  return { skipped: true, reason: "already-enriched", at: marker.at };
}

// Step 2 — load the issue and build a stable runbook URL from the key + a summary slug.
const issue = await api.getIssue(key);
const f = (issue && issue.fields) || {};
const summary = (f.summary || "").toString();
const slug = summary.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 60) || "incident";
const runbookUrl = "https://runbooks.example.com/" + projectKey + "/" + key + "/" + slug;

// Step 3 — attach the runbook as a remote link (best-effort; failure must not abort the chain).
let remoteLinkId = null;
try {
  const rl = await api.addRemoteLink(runbookUrl, "Runbook: " + key);
  remoteLinkId = rl && rl.id;
  api.log("Added runbook remote link: " + runbookUrl);
} catch (e) {
  api.log("addRemoteLink failed: " + e.message);
}

// Step 4 — compute a triage worklog duration by priority, padded by issue age. Clamp 5min..2h.
const priorityName = (f.priority && f.priority.name) || "Medium";
const baseByPriority = { Highest: 1800, High: 1200, Medium: 600, Low: 300, Lowest: 300 };
let seconds = baseByPriority[priorityName] != null ? baseByPriority[priorityName] : 600;
try {
  if (f.created) {
    const ageMs = Date.now() - new Date(f.created).getTime();
    const ageDays = Math.max(0, Math.floor(ageMs / 86400000));
    seconds += Math.min(ageDays, 30) * 60; // +1 min per day open, capped at 30 days
  }
} catch (e) {
  api.log("age padding skipped: " + e.message);
}
seconds = Math.max(300, Math.min(seconds, 7200));

let worklogId = null;
try {
  const wl = await api.addWorklog(seconds, "Automated triage bootstrap for " + priorityName + " incident");
  worklogId = wl && wl.id;
  api.log("Logged " + seconds + "s of triage work.");
} catch (e) {
  api.log("addWorklog failed: " + e.message);
}

// Step 5 — cross-issue branch: link up to 3 OTHER open incidents sharing the first component.
let linked = [];
try {
  const comp = (f.components && f.components[0] && f.components[0].name) || null;
  if (comp) {
    const esc = comp.replace(/"/g, '\\"');
    const jql = "project = " + projectKey + " AND component = \"" + esc + "\" AND statusCategory != Done AND key != " + key + " ORDER BY created DESC";
    const r = await api.searchJql(jql);
    const arr = Array.isArray(r) ? r : (r && r.issues) || [];
    for (const sib of arr.slice(0, 3)) {
      try {
        await api.createIssueLink(sib.key, "Relates");
        linked.push(sib.key);
      } catch (le) {
        api.log("link to " + sib.key + " failed: " + le.message);
      }
    }
    api.log("Cross-linked " + linked.length + " sibling incident(s) in component \"" + comp + "\".");
  } else {
    api.log("No component set - skipping sibling cross-link.");
  }
} catch (e) {
  api.log("sibling cross-link step failed: " + e.message);
}

// Step 6 — persist the idempotency marker. THIS is what makes every re-fire a no-op.
const stamp = {
  provisioned: true,
  at: new Date().toISOString(),
  runbookUrl: runbookUrl,
  remoteLinkId: remoteLinkId,
  worklogId: worklogId,
  worklogSeconds: seconds,
  linked: linked,
};
try {
  await api.setProperty(MARKER, stamp);
  api.log("Marker property set - future fires will be no-ops.");
} catch (e) {
  api.log("setProperty marker FAILED - rule may re-run on next fire: " + e.message);
}

// Step 7 — post a one-time ADF summary comment.
const bullets = [
  "Runbook: " + runbookUrl,
  "Triage time logged: " + Math.round(seconds / 60) + " min (" + priorityName + ")",
  linked.length ? "Cross-linked incidents: " + linked.join(", ") : "No sibling incidents linked",
];
const adf = {
  type: "doc",
  version: 1,
  content: [
    { type: "heading", attrs: { level: 3 }, content: [{ type: "text", text: "Incident runbook provisioned" }] },
    {
      type: "bulletList",
      content: bullets.map(function (b) {
        return { type: "listItem", content: [{ type: "paragraph", content: [{ type: "text", text: b }] }] };
      }),
    },
  ],
};
try {
  await api.addComment(adf);
} catch (e) {
  api.log("addComment failed: " + e.message);
}

return { enriched: true, runbookUrl: runbookUrl, worklogSeconds: seconds, linked: linked, remoteLinkId: remoteLinkId, worklogId: worklogId };

const MARKER = "cogni-change-record";
const key = api.context.issueKey;
const projectKey = (api.context && api.context.projectKey) || key.split("-")[0];

// Step 1 — idempotency gate: existing marker => this is a re-fire => do nothing.
let rec = null;
try {
  rec = await api.getProperty(MARKER);
} catch (e) {
  api.log("marker read failed, treating absent: " + e.message);
}
if (rec && rec.recorded) {
  api.log("Change record already created " + rec.at + " (dashboard " + rec.dashboardUrl + "). No-op re-fire.");
  return { skipped: true, reason: "already-recorded", at: rec.at };
}

// Step 2 — load issue; derive a service name from a "svc:*" label, else the project key.
const issue = await api.getIssue(key);
const f = (issue && issue.fields) || {};
const labels = Array.isArray(f.labels) ? f.labels : [];
const svcLabel = labels.find(function (l) { return /^svc[:-]/i.test(l); });
const service = svcLabel ? svcLabel.replace(/^svc[:-]/i, "") : projectKey.toLowerCase();
const svcSafe = service.replace(/[^a-z0-9._-]/gi, "-");
const dashboardUrl = "https://grafana.example.com/d/deploy/" + svcSafe + "?var-issue=" + key;

// Step 3 — attach the deploy dashboard as a remote link.
let dashId = null;
try {
  const rl = await api.addRemoteLink(dashboardUrl, "Deploy dashboard: " + service);
  dashId = rl && rl.id;
  api.log("Attached deploy dashboard: " + dashboardUrl);
} catch (e) {
  api.log("addRemoteLink failed: " + e.message);
}

// Step 4 — reconcile effort AND collect still-open blockers from issuelinks (branching input).
const subtasks = Array.isArray(f.subtasks) ? f.subtasks : [];
const links = Array.isArray(f.issuelinks) ? f.issuelinks : [];
let openBlockers = [];
for (const ln of links.slice(0, 50)) {
  const typeName = (ln.type && ln.type.name) || "";
  const inward = ln.inwardIssue; // present when THIS issue "is blocked by" inward
  if (inward && /block/i.test(typeName)) {
    const cat = inward.fields && inward.fields.status && inward.fields.status.statusCategory;
    const done = cat && (cat.key === "done" || cat.name === "Done");
    if (!done) openBlockers.push(inward.key);
  }
}
let seconds = 600 + subtasks.length * 300 + openBlockers.length * 180;
seconds = Math.max(600, Math.min(seconds, 14400)); // clamp 10min .. 4h
let worklogId = null;
try {
  const wl = await api.addWorklog(seconds, "Deployment + verification effort for " + key);
  worklogId = wl && wl.id;
  api.log("Reconciled " + seconds + "s across " + subtasks.length + " subtask(s).");
} catch (e) {
  api.log("addWorklog failed: " + e.message);
}

// Step 5 — branch: flag open blockers (merge-safe label) + cross-link co-shipped issues.
if (openBlockers.length) {
  try {
    await api.addLabels("deployed-with-open-blockers");
    api.log("WARNING: deployed with " + openBlockers.length + " open blocker(s): " + openBlockers.join(", "));
  } catch (e) {
    api.log("addLabels failed: " + e.message);
  }
}
let coShipped = [];
try {
  const relLabel = labels.find(function (l) { return /^release[:-]/i.test(l); });
  if (relLabel) {
    const esc = relLabel.replace(/"/g, '\\"');
    const jql = "project = " + projectKey + " AND labels = \"" + esc + "\" AND key != " + key + " ORDER BY updated DESC";
    const r = await api.searchJql(jql);
    const arr = Array.isArray(r) ? r : (r && r.issues) || [];
    for (const sib of arr.slice(0, 3)) {
      try {
        await api.createIssueLink(sib.key, "Relates");
        coShipped.push(sib.key);
      } catch (le) {
        api.log("co-ship link to " + sib.key + " failed: " + le.message);
      }
    }
    api.log("Linked " + coShipped.length + " co-shipped issue(s) under \"" + relLabel + "\".");
  } else {
    api.log("No release:* label - skipping co-ship linking.");
  }
} catch (e) {
  api.log("co-ship step failed: " + e.message);
}

// Step 6 — persist the marker (turns every subsequent fire into a no-op).
const stamp = {
  recorded: true,
  at: new Date().toISOString(),
  dashboardUrl: dashboardUrl,
  dashId: dashId,
  worklogId: worklogId,
  effortSeconds: seconds,
  subtaskCount: subtasks.length,
  openBlockers: openBlockers,
  coShipped: coShipped,
};
try {
  await api.setProperty(MARKER, stamp);
  api.log("Change-record marker set - future fires are no-ops.");
} catch (e) {
  api.log("setProperty FAILED - may re-run: " + e.message);
}

// Step 7 — post the ADF change-record comment (conditional sections).
const lines = [
  {
    type: "paragraph",
    content: [
      { type: "text", text: "Deploy dashboard: " },
      { type: "text", text: dashboardUrl, marks: [{ type: "link", attrs: { href: dashboardUrl } }] },
    ],
  },
  { type: "paragraph", content: [{ type: "text", text: "Reconciled effort: " + Math.round(seconds / 60) + " min across " + subtasks.length + " subtask(s)." }] },
];
if (coShipped.length) {
  lines.push({ type: "paragraph", content: [{ type: "text", text: "Co-shipped: " + coShipped.join(", ") }] });
}
if (openBlockers.length) {
  lines.push({
    type: "paragraph",
    content: [{ type: "text", text: "Deployed with open blockers: " + openBlockers.join(", "), marks: [{ type: "strong" }] }],
  });
}
const adf = {
  type: "doc",
  version: 1,
  content: [{ type: "heading", attrs: { level: 3 }, content: [{ type: "text", text: "Change record" }] }].concat(lines),
};
try {
  await api.addComment(adf);
} catch (e) {
  api.log("addComment failed: " + e.message);
}

return { recorded: true, dashboardUrl: dashboardUrl, effortSeconds: seconds, subtaskCount: subtasks.length, openBlockers: openBlockers, coShipped: coShipped, worklogId: worklogId, dashId: dashId };
